INSERT INTO knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status) SELECT 'f5aa6f4e-16ea-57eb-96bb-fb12daa45f39', e.id, l.id, s.id, NULL, 'N5 文字词汇', 'N5 级别的文字词汇知识点入口。', '请先按下方主题练习，再结合题目结果定位具体薄弱点。', '按主题选择题目进行练习。', 'published' FROM exams e JOIN exam_levels l ON l.exam_id = e.id JOIN subjects s ON s.exam_id = e.id WHERE e.code = 'jlpt' AND l.code = 'n5' AND s.code = 'vocabulary' ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status) SELECT '79b6bd66-4384-5416-99cf-9514e0e69d36', e.id, l.id, s.id, 'f5aa6f4e-16ea-57eb-96bb-fb12daa45f39', '汉字读音与表记', '掌握 N4/N5 常见汉字的读音、表记和基本词形。', '音读、训读或相似汉字的读音容易混淆。', '毎朝、新聞を読みます。', 'published' FROM exams e JOIN exam_levels l ON l.exam_id = e.id JOIN subjects s ON s.exam_id = e.id WHERE e.code = 'jlpt' AND l.code = 'n5' AND s.code = 'vocabulary' ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status) SELECT '9cfd9a81-f5b1-5433-82e0-0f5114194180', e.id, l.id, s.id, 'f5aa6f4e-16ea-57eb-96bb-fb12daa45f39', '词义与近义辨析', '根据句子语境选择词义准确的基础词汇。', '只按中文直译选词，忽略搭配和上下文。', '駅の前で友だちに会いました。', 'published' FROM exams e JOIN exam_levels l ON l.exam_id = e.id JOIN subjects s ON s.exam_id = e.id WHERE e.code = 'jlpt' AND l.code = 'n5' AND s.code = 'vocabulary' ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status) SELECT 'c4440a0c-f2f6-5460-9336-49b07ff7b4e5', e.id, l.id, s.id, 'f5aa6f4e-16ea-57eb-96bb-fb12daa45f39', '词语搭配与语境', '掌握高频词汇在具体句型和生活场景中的自然用法。', '知道单词意思，却不能判断与动词、助词或场景的搭配。', '薬を飲んで、早く寝ます。', 'published' FROM exams e JOIN exam_levels l ON l.exam_id = e.id JOIN subjects s ON s.exam_id = e.id WHERE e.code = 'jlpt' AND l.code = 'n5' AND s.code = 'vocabulary' ON CONFLICT (id) DO NOTHING;
