INSERT INTO knowledge_points (id, exam_id, level_id, subject_id, parent_id, name, description, common_mistakes, examples, status) SELECT '52daf21c-bb98-5463-b6fb-59c3414d75c1', e.id, l.id, s.id, '2d7157f8-afb7-58a0-85ea-b3d775f216a2', '基本句型与指示词', '掌握判断、存在、指示和疑问等基础句型。', '把指示词、疑问词和助词的功能混在一起。', 'これは新しい本です。', 'published' FROM exams e JOIN exam_levels l ON l.exam_id = e.id JOIN subjects s ON s.exam_id = e.id WHERE e.code = 'jlpt' AND l.code = 'n5' AND s.code = 'grammar' ON CONFLICT (id) DO NOTHING;
