INSERT INTO material_versions (id, material_id, version_no, title, content) VALUES ('7bc66d81-8006-5501-9b83-65d2e15fdb3c', 'd6aa210d-2d4c-5020-8db1-75619ee50ed2', 1, 'N5·第10单元·实战训练·問題3阅读短文', 'A「田中さん、おはようございます。」
INSERT INTO materials (id) VALUES ('88780a4c-a5cb-568b-bdc1-c5745111311f') ON CONFLICT (id) DO NOTHING;
INSERT INTO material_versions (id, material_id, version_no, title, content) VALUES ('73fb750b-8316-53a7-8a27-60c055e73255', '88780a4c-a5cb-568b-bdc1-c5745111311f', 1, 'N4·第1单元·实战训练·問題3阅读短文', 'クラスメートの神田さんがずっと京都へ行き［21］。卒業旅行の目的地が京都だと聞いた時、彼女はとてもうれし［22］でした。京都に着いた神田さんはまず金閣寺を［23］に行きました。はじめ［24］金閣寺を見た神田さんが［25］ように喜んでいました。') ON CONFLICT (id) DO NOTHING;
INSERT INTO materials (id) VALUES ('ffd427b8-d1ff-5337-8303-0cc13a6e3cb7') ON CONFLICT (id) DO NOTHING;
INSERT INTO material_versions (id, material_id, version_no, title, content) VALUES ('3beeee0d-f3cd-5c97-bdaa-2ab2e196374c', 'ffd427b8-d1ff-5337-8303-0cc13a6e3cb7', 1, 'N4·第2单元·实战训练·問題3阅读短文', '今日は友達と一緒に遊園地に行きました。人がたくさん並んで［21］が、みんな静かでした。遊園地に入った後、友達に［22］ジェットコースターまで乗りました。最初は怖くて乗りたくなかったんですが、結局乗って［23］。実はそんなに怖くなかった［24］。私たちは夜8時までずっと遊んでいました。家に帰った後、自分がジェットコースターに乗った［25］を両親に話しました。') ON CONFLICT (id) DO NOTHING;
INSERT INTO materials (id) VALUES ('f5d13999-a1e9-5813-a832-27d3e76cdc49') ON CONFLICT (id) DO NOTHING;
INSERT INTO material_versions (id, material_id, version_no, title, content) VALUES ('d2122352-c4e3-5c0a-a757-22447dd13922', 'f5d13999-a1e9-5813-a832-27d3e76cdc49', 1, 'N4·第3单元·实战训练·問題3阅读短文', '今日は友達と博物館へ行きました。ガイドさんの話では、写真を撮っても［21］が、手で［22］。午後3時に母から電話がかかってきました。まだ［23］んですが、もう［24］なりません。写真をいっぱい撮りましたから、うれしかったです。今日のことはきっと［25］思い出になります。') ON CONFLICT (id) DO NOTHING;
INSERT INTO materials (id) VALUES ('bf71bb09-8ab4-5918-9147-87364f32e94c') ON CONFLICT (id) DO NOTHING;
INSERT INTO material_versions (id, material_id, version_no, title, content) VALUES ('f8677e1f-b3f7-5832-9c00-6bc612f0773b', 'bf71bb09-8ab4-5918-9147-87364f32e94c', 1, 'N4·第4单元·实战训练·問題3阅读短文', '12月31日は大晦日ともいいます。除夜の鐘を［21］ながら、年越しそばを食べます。幸せがそばのように長く続く［22］と祈ります。昔は、前日［23］お正月の準備を終えなければなりません。みんなで門松を家の入り口に［24-a］、部屋の掃除を［24-b］します。そして、大晦日の夜も［25］ず、新年を迎えます。
INSERT INTO materials (id) VALUES ('e181c8b9-e451-536b-a82a-9f562e4cf72a') ON CONFLICT (id) DO NOTHING;
INSERT INTO material_versions (id, material_id, version_no, title, content) VALUES ('898b3104-55b9-536f-b0a0-cf8f378eedb0', 'e181c8b9-e451-536b-a82a-9f562e4cf72a', 1, 'N4·第5单元·实战训练·問題3阅读短文', '3月3日は日本の雛祭り（注）です。その日に女の子［21］いる家に人形を飾ります。その人形は女の子が元気に成長する［22］という願いが込められています。普通の人形は四段［23］ありますが、最近は七、八段［24］あるものが売り出されています。しかし最近はこれを飾らない家の［25］多くなりました。
INSERT INTO materials (id) VALUES ('c388b938-b10a-50c9-956e-f4d88459ff8d') ON CONFLICT (id) DO NOTHING;
INSERT INTO material_versions (id, material_id, version_no, title, content) VALUES ('df3f55cd-7919-595b-bde9-93a1b9e294c9', 'c388b938-b10a-50c9-956e-f4d88459ff8d', 1, 'N4·第6单元·实战训练·問題3阅读短文', 'メーカーが売り残ったり傷ついたりした製品を、安い値段で売る［21］作った店を「アウトレット店」［22］。「アウトレット」というのは、もともと米国で始まったシステムですが、だんだん世界に広がる［23］。日本では、衣類や食器［24］、日用品、スポーツ用品など、いろいろなメーカーのアウトレット店がここ数年のあいだに、できて［25］。') ON CONFLICT (id) DO NOTHING;
INSERT INTO materials (id) VALUES ('db0bb10a-bed3-54a0-9ef6-591978853ad1') ON CONFLICT (id) DO NOTHING;
INSERT INTO material_versions (id, material_id, version_no, title, content) VALUES ('eb908acd-4377-58f4-b73f-01431489415d', 'db0bb10a-bed3-54a0-9ef6-591978853ad1', 1, 'N4·第7单元·实战训练·問題3阅读短文', '柔道の特長は「柔能く剛を制す」と言われている。これは弱いものでも強いものに勝つ［21］という意味です。つまり、相手の力を上手に利用すれ［22］、強い相手でも倒す［23］のだ。調査［24］、現在世界の柔道人口は600万人を超えたそうです。柔道を練習する人達は帯の色でその人の実力を推測することが［25］。') ON CONFLICT (id) DO NOTHING;
INSERT INTO materials (id) VALUES ('b75b44d9-0d1f-5215-8f7b-2ffd0f5c987e') ON CONFLICT (id) DO NOTHING;
INSERT INTO material_versions (id, material_id, version_no, title, content) VALUES ('8e601602-6445-5c8d-863c-b03405d16bbc', 'b75b44d9-0d1f-5215-8f7b-2ffd0f5c987e', 1, 'N4·第8单元·实战训练·問題3阅读短文', '世界一物価が高いと言われている東京で留学生活を［21］と思ったら、節約することが必要だ。アルバイト［22］で生活することは実際には不可能だと考えてください。その上、最近の不景気の影響で、アルバイト先を見つけることがますます難しくなっている。家賃を節約する［23］、友人同士などで一部屋を借りて共同生活することが［24］あいだに広まっている。留学生［25］、日本人も他人と生活することに嫌な感じがなくなっているようだ。') ON CONFLICT (id) DO NOTHING;
INSERT INTO materials (id) VALUES ('81702a2b-2a7a-557d-a410-b0e76b47f8d1') ON CONFLICT (id) DO NOTHING;
INSERT INTO material_versions (id, material_id, version_no, title, content) VALUES ('15a0eb53-8f1f-5fd9-9645-fe199e8675bd', '81702a2b-2a7a-557d-a410-b0e76b47f8d1', 1, 'N4·第9单元·实战训练·問題3阅读短文', '先日は楽しい旅行のお話をお聞かせいただいて、ありがとう［21］。実は今、わたしも旅行先で手紙を書いています。先週からずっと［22］と思っていた秋の京都に来てしまいました。先生がおいしい［23］お土産の紅葉焼きを買いました［24］、早速お送りしました。どうぞ召し上がって［25］。この手紙が届く頃には、もう東京に戻っていると思いますので、先生のお宅にお伺いしたいと思います。') ON CONFLICT (id) DO NOTHING;
INSERT INTO materials (id) VALUES ('73543c05-f81a-5190-b79b-19fa98319fe3') ON CONFLICT (id) DO NOTHING;
INSERT INTO material_versions (id, material_id, version_no, title, content) VALUES ('25bf7d47-2e86-5b79-9638-8b7994ecbf4d', '73543c05-f81a-5190-b79b-19fa98319fe3', 1, 'N4·第10单元·实战训练·問題3阅读短文', '寒中お見舞い［21］。大変ご無沙汰しております。皆様お変わりが［22］か。今はインフルエンザにかかったから、自宅で休養して［23］。病気が治るまで、ずっと休む［24］です。寒さ厳しき折、お体にはお気をつけて［25］。') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, status, has_answer) VALUES ('db6c5846-7b88-5423-a54d-78504a1b634a', 'published', true) ON CONFLICT (id) DO NOTHING;
