INSERT INTO answer_keys (question_version_id, value, authority, explanation) VALUES ('3056dc57-df1e-5530-af9c-29075bd5602e', '{"reference":"例：田中さんは学生です。\n\n名词谓语句 |  | 肯定形 | 否定形\n敬体形 | 现在时 | 学生です | 学生ではありません\n敬体形 | 过去时 | 学生でした | 学生ではありませんでした\n简体形 | 现在时 | 学生だ | 学生ではない\n简体形 | 过去时 | 学生だった | 学生ではなかった"}'::jsonb, 'official', '') ON CONFLICT (question_version_id) DO NOTHING;
